package com.profa.booking;import org.springframework.security.core.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/bookings")public class BookingController{final BookingRepository r;public BookingController(BookingRepository r){this.r=r;}@GetMapping public List<Booking> list(){return r.findAll();}@PostMapping public Booking create(Authentication a,@RequestBody Booking x){x.setParentId(UUID.fromString(a.getName()));return r.save(x);}@PatchMapping("/{id}/status")public Booking status(@PathVariable UUID id,@RequestParam String value){Booking x=r.findById(id).orElseThrow();x.setStatus(value);return r.save(x);}}